function u_s_out = mfun_smcvc_current_controller(i_s_ref_in, fbk_in, u_c_lim_ab_in, enable, p)
%MFUN_SMCVC_CURRENT_CONTROLLER Block CurrentController of the control system.
%   CurrentController of motulator. Generated by motulator_export from the MATLAB port
%   of motulator and called by the MATLAB Function block of the library of motulator,
%   whose folder motulator.setup adds to the MATLAB path. The parameters are the fields
%   of the struct p (from the mask, [] as NaN). The state is in persistent variables, of
%   which each MATLAB Function block has its own copy. The inputs without direct
%   feedthrough come through unit delays, so the update of the state with them is done
%   at the next call.
persistent self pending
if isempty(self)
    % Machine model: SaturatedSynchronousMachinePars with a GradNet flux map, or
    % SynchronousMachinePars with constant inductances
    par = machine_pars(p);
    self = sm_current_ctrl_init(par, p.alpha_c, p.alpha_i, p.discrete, p.T_s);
    % Feedback signals of the sampling period, for its update done at the next call
    self.fbk_u_s = complex(0);
    self.fbk_w_c = 0;
    self.fbk_theta_c = 0;
    pending = false;
end
% Update of the previous sampling period with its inputs (the inputs
% u_c_lim_ab, enable through unit delays)
if pending
    u_c_lim_ab = complex_in(u_c_lim_ab_in);
    % The discrete-time controller takes its limited output, except with blocked
    % gates, when the open-circuit voltage of the observer is the realized one
    u = self.fbk_u_s;
    if self.discrete && enable > 0
        u = exp(-1i*self.fbk_theta_c)*u_c_lim_ab;
    end
    self = sm_current_ctrl_update(self, p.T_s, u, self.fbk_w_c);
end
pending = true;
i_s_ref = complex_in(i_s_ref_in);
fbk = observer_outputs_unpack(fbk_in);
% Preset at the back-EMF of the caught speed
% (CurrentVectorController.get_feedback)
if fbk.caught
    self = sm_current_ctrl_preset(self, 1i*fbk.w_m*fbk.psi_f, fbk.w_c);
end
[self, u_s] = sm_current_ctrl_compute_output(self, i_s_ref, fbk.i_s);
self.fbk_u_s = fbk.u_s;
self.fbk_w_c = fbk.w_c;
self.fbk_theta_c = fbk.theta_c;
u_s_out = complex_out(u_s);
end

function par = machine_pars(p)
%MACHINE_PARS Machine model from the parameters par_* and gn_* of the block:
%   SaturatedSynchronousMachinePars with a GradNet flux map, or
%   SynchronousMachinePars with constant inductances.
if isnan(p.gn_in_dim)
    par = synchronous_machine_pars(p.par_n_p, p.par_R_s, p.par_L_d, p.par_L_q, ...
        p.par_psi_f, gradnet_placeholder());
else
    flux_map = gradnet(p.gn_in_dim, p.gn_mu_dim, p.gn_W, p.gn_b, p.gn_mu_log, ...
        p.gn_bias, p.gn_activation, p.gn_beta_log, p.gn_p, p.gn_in_base, ...
        p.gn_out_base);
    par = saturated_synchronous_machine_pars(p.par_n_p, p.par_R_s, flux_map);
end
end

function s = observer_outputs_unpack(u)
%OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'e_o', complex(u(9), u(10)), ...
    'eps', u(11), ...
    'eps_f', u(12), ...
    'psi_a', complex(u(13), u(14)), ...
    'tau_M', u(15), ...
    'w_c', u(16), ...
    'w_m', u(17), ...
    'w_M', u(18), ...
    'theta_c', u(19), ...
    'theta_m', u(20), ...
    'psi_f', u(21), ...
    'h', u(22), ...
    'caught', u(23));
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function self = complex_pi_init(k_p, k_i, k_t)
%COMPLEX_PI_INIT 2DOF synchronous-frame complex-vector PI controller
%   (ComplexPIController).
self = struct('k_p', k_p, 'k_t', k_t, 'alpha_i', k_i/k_t, 'u_i', complex(0), ...
    'v', complex(0));
end

function [self, u] = complex_pi_compute_output(self, i_ref, i, u_ff)
%COMPLEX_PI_COMPUTE_OUTPUT Controller output.
% Disturbance input estimate
self.v = self.u_i - (self.k_p - self.k_t)*i + u_ff;
u = self.k_t*(i_ref - i) + self.v;
end

function self = complex_pi_update(self, T_s, u, w_c)
%COMPLEX_PI_UPDATE Update the integral state with the realized output u.
self.u_i = self.u_i + T_s*(self.alpha_i + 1i*w_c)*(u - self.v);
end

function self = discrete_complex_init(alpha_c, T_s)
%DISCRETE_COMPLEX_INIT Direct discrete-time 2DOF complex-vector controller
%   (DiscreteComplexController), whose design includes the computational delay, so
%   that the angle of the output is not advanced (k_comp = 0 in the control system).
self = struct('T_s', T_s, 'beta', exp(-alpha_c*T_s), 'u_i', complex(0), ...
    'u_lim', complex(0), 'w_c', 0, 'e', complex(0), 'u', complex(0));
end

function k = discrete_complex_gains(self, w_c)
%DISCRETE_COMPLEX_GAINS Gains [k_t k_i k_1 k_2] of the complex-vector design
%   (_gains).
T_s = self.T_s;
beta = self.beta;
Phi = exp(-1i*w_c*T_s); % Rotation of the coordinates over T_s
Phi2 = Phi*Phi;
k = [(1 - beta)/(Phi2*T_s), (1 - beta)*(1 - beta*Phi)/(Phi2*T_s*T_s), ...
    (1 - beta)*(1 + (1 - beta)/Phi + 1/Phi2)/T_s, (1 - beta)*(1 + Phi)];
end

function [self, u] = discrete_complex_compute_output(self, i_ref, i)
%DISCRETE_COMPLEX_COMPUTE_OUTPUT Controller output.
k = discrete_complex_gains(self, self.w_c);
self.e = i_ref - i;
self.u = k(1)*i_ref - k(3)*i - k(4)*self.u_lim + self.u_i;
u = self.u;
end

function self = discrete_complex_update(self, T_s, u, w_c)
%DISCRETE_COMPLEX_UPDATE Update with the limited output u and the angular speed w_c
%   of the coordinates.
k = discrete_complex_gains(self, self.w_c);
self.u_i = self.u_i + T_s*k(2)*(self.e - (self.u - u)/k(1));
self.u_lim = complex(u);
self.w_c = w_c;
end

function self = discrete_complex_preset(self, u, w_c)
%DISCRETE_COMPLEX_PRESET Preset the integral state to the steady state of the
%   output u (preset).
self.w_c = w_c;
k = discrete_complex_gains(self, w_c);
self.u_i = (1 + k(4))*u;
end

function net = gradnet(in_dim, mu_dim, W, b, mu_log, bias, activation, beta_log, ...
    p, in_base, out_base)
%GRADNET GradNet from its parameters (the fields of the GradNet structs of the
%   model initialization), W being an embed_dim-by-in_dim matrix. The field mu has
%   the gains of the linear term, zero for the inputs beyond the first mu_dim.
mu = zeros(size(W, 2), 1);
n_mu = min(mu_dim, numel(mu_log));
mu(1:n_mu) = exp(mu_log(1:n_mu));
net = struct('in_dim', in_dim, 'mu_dim', mu_dim, 'embed_dim', size(W, 1), ...
    'W', W, 'b', b(:), 'mu', mu, 'bias', bias(:), 'activation', activation, ...
    'beta', exp(beta_log), 'p', p, 'in_base', in_base, 'out_base', out_base);
end

function net = gradnet_placeholder()
%GRADNET_PLACEHOLDER GradNet with in_dim = 2 for the machine models without a flux
%   map, so that the code using a flux map compiles.
net = gradnet(2, 0, zeros(1, 2), 0, zeros(2, 1), zeros(2, 1), 2, 0, 1, 1, 1);
end

function [z, jac] = gradnet_forward(net, x, want_jac)
%GRADNET_FORWARD Output of the network for a per-unit input x (a column vector),
%   as GradNetFunction.__call__. If want_jac is true, the Jacobian matrix is
%   computed too. The Jacobians of both activations are of the form
%   c*(diag(d) - u*u^T), so the Jacobian of the network is
%   diag(mu) + c*(W^T diag(d) W - v*v^T) with v = W^T u.
W = net.W;
beta = net.beta;
% Module: W^T act(W x + b)
h = beta*(W*x + net.b);
if net.activation == 1
    % PNormGradient: x^q/(1 + sum(x^(q + 1)))^(q/(q + 1)) with q = p - 1
    q = net.p - 1;
    norm_ = 1 + sum(h.^(q + 1));
    norm_r = norm_^(q/(q + 1));
    c = beta*q/norm_r;
    d = h.^(q - 1);
    u = h.^q/sqrt(norm_);
    h = h.^q/norm_r;
else
    % Softmax
    h = exp(h - max(h));
    h = h/sum(h);
    c = beta;
    d = h;
    u = h;
end
% Linear term (for the first mu_dim inputs), bias, and the module
z = net.mu.*x + net.bias + W'*h;
jac = zeros(size(W, 2));
if want_jac
    v = W'*u;
    jac = diag(net.mu) + c*(W'*(d.*W) - v*v');
end
end

function y = gradnet_map(net, x)
%GRADNET_MAP Evaluate the map (FluxMap or CurrentMap in motulator), symmetrized
%   about the d-axis. The input and output are in SI units.
% Evaluate at the input and its conjugate, and symmetrize about the d-axis
x1 = [real(x); imag(x)]/net.in_base;
x2 = [x1(1); -x1(2)];
z1 = gradnet_forward(net, x1, false);
z2 = gradnet_forward(net, x2, false);
y = 0.5*((z1(1) + 1i*z1(2)) + conj(z2(1) + 1i*z2(2)));
y = y*net.out_base;
end

function jac = gradnet_map_jacobian(net, x)
%GRADNET_MAP_JACOBIAN Jacobian matrix [dy_d/dx_d, dy_d/dx_q; dy_q/dx_d, dy_q/dx_q]
%   of the map (CurrentMap.jacobian in motulator) in SI units.
% Symmetrize as in gradnet_map: the conjugation flips the signs of the off-diagonal
% elements
x1 = [real(x); imag(x)]/net.in_base;
x2 = [x1(1); -x1(2)];
[~, jac1] = gradnet_forward(net, x1, true);
[~, jac2] = gradnet_forward(net, x2, true);
jac = 0.5*(net.out_base/net.in_base)*(jac1 + [1, -1; -1, 1].*jac2);
end

function par = synchronous_machine_pars(n_p, R_s, L_d, L_q, psi_f, flux_map)
%SYNCHRONOUS_MACHINE_PARS Constant inductances (SynchronousMachinePars), with an
%   unused flux map.
par = struct('n_p', n_p, 'R_s', R_s, 'L_d', L_d, 'L_q', L_q, 'psi_f', psi_f, ...
    'saturated', false, 'flux_map', flux_map, 'L_d0', 0, 'L_q0', 0);
end

function par = saturated_synchronous_machine_pars(n_p, R_s, flux_map)
%SATURATED_SYNCHRONOUS_MACHINE_PARS GradNet flux map
%   (SaturatedSynchronousMachinePars).
par = struct('n_p', n_p, 'R_s', R_s, 'L_d', 0, 'L_q', 0, 'psi_f', 0, ...
    'saturated', true, 'flux_map', flux_map, 'L_d0', 0, 'L_q0', 0);
% As in SaturatedSynchronousMachinePars.__post_init__
par.psi_f = real(psi_s_dq(par, complex(0)));
L0 = incr_ind_mat(par, complex(0));
par.L_d0 = L0.L_dd;
par.L_q0 = L0.L_qq;
if par.psi_f < 1e-3 % EPS of motulator/drive/utils/_parameters.py
    par.psi_f = 0; % No permanent magnets
end
end

function psi_s = psi_s_dq(par, i_s)
%PSI_S_DQ Stator flux linkage as a function of the stator current.
if par.saturated
    psi_s = gradnet_map(par.flux_map, i_s);
else
    psi_s = par.L_d*real(i_s) + par.psi_f + 1i*par.L_q*imag(i_s);
end
end

function L = incr_ind_mat(par, i_s)
%INCR_IND_MAT Incremental inductance matrix [L_dd, L_dq; L_dq, L_qq] as a struct.
if ~par.saturated
    L = struct('L_dd', par.L_d, 'L_dq', 0, 'L_qq', par.L_q);
    return
end
jac = gradnet_map_jacobian(par.flux_map, i_s);
L = struct('L_dd', jac(1, 1), 'L_dq', jac(1, 2), 'L_qq', jac(2, 2));
end

function self = sm_current_ctrl_init(par, alpha_c, alpha_i, discrete, T_s)
%SM_CURRENT_CTRL_INIT Current controller: a complex-vector PI controller of the flux
%   linkages (CurrentController; alpha_i = NaN means alpha_c) or, if discrete is
%   true, the direct discrete-time controller (DiscreteCurrentController).
if isnan(alpha_i)
    alpha_i = alpha_c;
end
k_t = alpha_c;
k_i = alpha_c*alpha_i;
k_p = alpha_c + alpha_i;
self = struct('par', par, 'discrete', logical(discrete), ...
    'pi', complex_pi_init(k_p, k_i, k_t), 'dc', discrete_complex_init(alpha_c, T_s));
end

function [self, u] = sm_current_ctrl_compute_output(self, i_ref, i)
%SM_CURRENT_CTRL_COMPUTE_OUTPUT Voltage reference, the currents mapped to the flux
%   linkages, which takes the saliency and the magnetic saturation into account.
psi_ref = psi_s_dq(self.par, i_ref) - self.par.psi_f;
psi = psi_s_dq(self.par, i) - self.par.psi_f;
if self.discrete
    [self.dc, u] = discrete_complex_compute_output(self.dc, psi_ref, psi);
else
    [self.pi, u] = complex_pi_compute_output(self.pi, psi_ref, psi, 0);
end
end

function self = sm_current_ctrl_update(self, T_s, u, w_c)
%SM_CURRENT_CTRL_UPDATE Update the states with the realized voltage u, or with the
%   limited voltage reference of the discrete-time controller.
if self.discrete
    self.dc = discrete_complex_update(self.dc, T_s, u, w_c);
else
    self.pi = complex_pi_update(self.pi, T_s, u, w_c);
end
end

function self = sm_current_ctrl_preset(self, u, w_c)
%SM_CURRENT_CTRL_PRESET Preset the integral state to the steady-state output u.
if self.discrete
    self.dc = discrete_complex_preset(self.dc, u, w_c);
else
    self.pi.u_i = u;
end
end
